symbols.example:
Полное дерево состояний
```tsx
import { AsyncBoundary } from '@reformer/cdk/async-boundary';

function ApplicationPage({ status, error, reload, form }: Props) {
return (
<AsyncBoundary.Root status={status} error={error} onRetry={reload} delayMs={200}>
<AsyncBoundary.Loading>
<p role="status" aria-live="polite">Загрузка заявки…</p>
</AsyncBoundary.Loading>

<AsyncBoundary.Error>
{({ error, retry }) => (
 <div role="alert" aria-live="assertive">
   <p>{String(error)}</p>
   <button onClick={retry}>Повторить</button>
 </div>
)}
</AsyncBoundary.Error>

<AsyncBoundary.Content>
<CreditForm form={form} />
</AsyncBoundary.Content>
</AsyncBoundary.Root>
);
}
```

symbols.signature:
export function AsyncBoundaryContent<T = unknown>({
  showWhileRefreshing = true,
  children,
}: AsyncBoundaryContentProps<T>)

export interface AsyncBoundaryContentProps<T = unknown> {
  /**
   * Показывать контент во время фонового обновления (`refreshing`).
   * @default true
   */
  showWhileRefreshing?: boolean;
  /**
   * Содержимое при `status === 'ready'`. В self-managed режиме можно передать
   * render-функцию — она получит загруженные данные уже суженными до `T`
   * (внутри `ready` они гарантированно есть).
   */
  children: ReactNode | ((data: T) => ReactNode);
}

export interface AsyncBoundaryContextValue<T = unknown, E = unknown> {
  /** Сырой статус из `AsyncBoundary.Root`. */
  status: AsyncStatus;
  /**
   * Загруженные данные — только в self-managed режиме (`load`). В controlled-режиме
   * всегда `undefined`: там данными владеет консумент.
   */
  data: T | undefined;
  /** `status === 'idle'` — загрузка не запускалась. */
  isIdle: boolean;
  /**
   * Показывать ли индикатор загрузки. Это НЕ `status === 'loading'`: при `delayMs > 0`
   * первые `delayMs` мс флаг остаётся `false`, чтобы быстрый ответ не вызывал вспышку спиннера.
   */
  isLoading: boolean;
  /** `status === 'ready'` — данные получены. */
  isReady: boolean;
  /** `status === 'error'` — запрос упал. */
  isError: boolean;
  /** Фоновое обновление поверх уже показанного контента. */
  refreshing: boolean;
  /** Ошибка (null, когда её нет). */
  error: E | null;
  /** Повторить загрузку. В self-managed режиме перезапускает `load`. */
  retry: () => void;
  /** Возможен ли повтор: задан `onRetry` либо работает self-managed режим. */
  canRetry: boolean;
  /** Сгенерированные id для a11y-связок. */
  ids: AsyncBoundaryIds;
  /**
   * Пропсы региона-обёртки (`aria-busy`, `data-status`). Лежат в контексте, а не только
   * в {@link useAsyncBoundary}, чтобы обёртка из ui-kit не пересчитывала ту же логику:
   * читать их можно только НИЖЕ провайдера, а сам `Root` разметки не рендерит.
   */
  rootProps: AsyncBoundaryRootPropGetters;
  /** Пропсы индикатора загрузки: `role="status"` + `aria-live="polite"`. */
  loadingProps: AsyncBoundaryLoadingPropGetters;
  /** Пропсы блока ошибки: `role="alert"` + `aria-live="assertive"`. */
  errorProps: AsyncBoundaryErrorPropGetters;
}

export interface AsyncBoundaryEmptyProps {
  /**
   * Показать вместо контента, когда загрузка успешна, но данных нет.
   * Пустота — ортогональная статусу ось: предикат считает консумент, а слот
   * рендерится только внутри `ready`.
   */
  when: boolean;
  /** Содержимое пустого состояния. */
  children: ReactNode;
}

export interface AsyncBoundaryErrorPropGetters {
  id: string;
  role: 'alert';
  'aria-live': 'assertive';
}

export interface AsyncBoundaryErrorProps<E = unknown> {
  /** Узел или render-функция, получающая `error` / `retry` / `canRetry`. */
  children: ReactNode | ((props: AsyncBoundaryErrorRenderProps<E>) => ReactNode);
}

export interface AsyncBoundaryErrorRenderProps<E = unknown> {
  /** Ошибка из `AsyncBoundary.Root`. */
  error: E | null;
  /** Повторить загрузку (no-op, если `onRetry` не задан). */
  retry: () => void;
  /** Задан ли `onRetry` — по нему решают, рисовать ли кнопку повтора. */
  canRetry: boolean;
}

export interface AsyncBoundaryHandle<T = unknown, E = unknown> {
  /** Перезапустить загрузку. В controlled-режиме вызывает `onRetry`. */
  reload: () => void;
  /** Прервать текущий запрос. Прерывание не считается ошибкой. В controlled-режиме — no-op. */
  abort: () => void;
  /** Снимок статуса на момент рендера. */
  status: AsyncStatus;
  /** Последние загруженные данные (только self-managed режим). */
  data: T | undefined;
  /** Снимок ошибки. */
  error: E | null;
  /** Идёт ли загрузка (с учётом `delayMs`). */
  isLoading: boolean;
  /** Идёт ли фоновое обновление. */
  refreshing: boolean;
}

